  ui_story_32180401_1_3_dialog_content = "Ya sea una tarea del Gremio de Explorador Nublar o tuya, Lady Sheol, la trataré con el mismo respeto.",
  ui_story_32180401_1_4_dialog_content = "Eres tan dulce, querido.",
