  ui_story_32180401_1_13_dialog_content = "(¿Está siendo chantajeada por un moroso particularmente astuto? Bueno, este no debería ser el caso, dado lo astuta que es la Señorita Sheol...)",
  ui_story_32180401_1_14_dialog_content = "(Pero a juzgar por sus expresiones, parece estar muy preocupada.)",
