  ui_story_32180401_1_28_dialog_content = "¡Has vuelto, mamá! Es tan maravilloso. Pensé que me habías abandonado y que nunca volverías!",
  ui_story_32180401_1_29_dialog_content = "Oye, ¿quién es éste?",
