  ui_story_32180401_1_40_dialog_content = "Tengo una deuda pendiente, pero el moroso se escapó y dejó al niño atrás como pago.",
  ui_story_32180401_1_41_dialog_content = "Entonces, ¿por qué soy el único que podría hacer este trabajo para ti? Vice sería una mejor opción para cuidar al niño.",
