  ui_story_32180401_1_44_dialog_content = "Correcto. Atraparon al irresponsable. Actualmente está \"expiando\" en algún lugar bajo la supervisión de Cloudrover.",
  ui_story_32180401_1_45_dialog_content = "Instruí a mis hombres para que lo \"interrogaran\" un poco, tratando de averiguar de dónde había secuestrado al niño, pero sin éxito.",
  ui_story_32180401_1_46_dialog_content = "Por lo tanto, la llevé a muchos lugares y le mostré muchas fotos. Pero aún no podía recordar dónde vivía.",
  ui_story_32180401_1_47_dialog_content = "Eventualmente, incluso me tomó como su madre.",
