  ui_story_32180401_1_52_dialog_content = "Has sido realmente amable con el niño, Señora Sheol.",
  ui_story_32180401_1_53_dialog_content = "Ay. Cada viaje para buscar su ciudad natal se convertiría en un viaje de placer para ella.",
  ui_story_32180401_1_54_dialog_content = "Ahora, Caelestita, eres el único que conozco que puede lidiar con esto.",
  ui_story_32180401_1_55_dialog_content = "Creo que sé lo que quieres decir.",
  ui_story_32180401_1_56_dialog_content = "¿Puedes recordar cómo era cuando estabas con tus padres, pequeña niña?",
  ui_story_32180401_1_57_dialog_content = "Sabes que la Señora Sheol te trata como a familia, ¿verdad?",
  ui_story_32180401_1_58_dialog_content = "Ejem...",
  ui_story_32180401_1_59_dialog_content = "Intenta recordar si tuviste sentimientos similares antes de conocer a la Sra. Sheol.",
  ui_story_32180401_1_60_dialog_content = "¡Está bien, lo intentaré!",
  ui_story_32180401_1_61_dialog_content = "¡Potencia de fuerza!",
  ui_story_32180401_1_62_dialog_content = "¿Quieres un panqueque, Elena?",
  ui_story_32180401_1_63_dialog_content = "¡Vamos al parque hoy, Elena!",
  ui_story_32180401_1_64_dialog_content = "Hora de levantarte, Elena. El sol ha estado fuera por un rato ahora.",
  ui_story_32180401_1_65_dialog_content = "¿Cómo es?",
