  ui_story_32180401_1_71_dialog_content = "<color=#e8d9bb>Varios días después</color>",
  ui_story_32180401_1_72_dialog_content = "¿Está resuelto el asunto?",
  ui_story_32180401_1_73_dialog_content = "Sí. Hablando de eso, ¡la red de información de Cloudrover es muy impresionante!",
  ui_story_32180401_1_74_dialog_content = "El niño estaba reacio, pero sí volvió con sus verdaderos padres.",
  ui_story_32180401_1_75_dialog_content = "Eso es bueno.",
  ui_story_32180401_1_76_dialog_content = "Dime, ¿por qué no querías venir, Señora Sheol?",
  ui_story_32180401_1_77_dialog_content = "¿Era eso necesario?",
  ui_story_32180401_1_78_dialog_content = "¿No quieres escuchar lo que Ele... los padres de ese niño tienen que decirte?",
  ui_story_32180401_1_79_dialog_content = "Solo algunas palabras de agradecimiento, supongo.",
  ui_story_32180401_1_80_dialog_content = "Estoy contento siempre y cuando el niño haya llegado a casa a salvo.",
  ui_story_32180401_1_81_dialog_content = "Puedes ser raro a veces, como ahora, cuando ni siquiera quieres saber el nombre de ese niño...",
  ui_story_32180401_1_82_dialog_content = "Ahora no es el momento para que me entere.",
  ui_story_32180401_1_83_dialog_content = "May Te hago una pregunta, Señora Sheol?",
  ui_story_32180401_1_84_dialog_content = "¡Dispara!",
  ui_story_32180401_1_85_dialog_content = "¿Por qué hacer caridad de repente?",
  ui_story_32180401_1_86_dialog_content = "¿Te parece una obra de caridad? ¿No has estado haciendo cosas similares todo este tiempo?",
  ui_story_32180401_1_87_dialog_content = "¿Qué? ¿Yo?",
  ui_story_32180401_1_88_dialog_content = "Esto no es una obra de caridad para mí.",
  ui_story_32180401_1_89_dialog_content = "Acabo de notar que la niña tenía un talento para los números mientras estaba conmigo.",
  ui_story_32180401_1_90_dialog_content = "Con un poco de entrenamiento, ella podría convertirse en una excelente contadora para Cloudrover.",
  ui_story_32180401_1_91_dialog_content = "Pareces seguro de que el niño trabajará para Cloudrover en el futuro, ¿no es así?",
  ui_story_32180401_1_92_dialog_content = "Bueno, eso es un secreto comercial.",
  ui_story_32180401_1_93_dialog_content = "Pero eso no tenía nada que ver con enviarla de vuelta a sus padres, ¿verdad?",
  ui_story_32180401_1_94_dialog_content = "Después de todo, mantenerla en el Gremio de Explorador Nublar es lo que haría un empresario astuto, ¿no es así?",
  ui_story_32180401_1_95_dialog_content = "Ahora no es el momento para eso.",
  ui_story_32180401_1_96_dialog_content = "O más bien, el mejor lugar para ella a su edad no es la guilda.",
  ui_story_32180401_1_97_dialog_content = "...",
  ui_story_32180401_1_98_dialog_content = "Pensé que harías la siguiente pregunta por costumbre.",
  ui_story_32180401_1_99_dialog_content = "Supongo que tú también has madurado. Quizás debería reevaluar mis evaluaciones de ti.",
  ui_story_32180401_1_100_dialog_content = "Probablemente te estás preguntando por qué me importaba ese niño, ¿verdad?",
  ui_story_32180401_1_101_dialog_content = "De hecho, noté que la niña tenía un talento para los números mientras estaba conmigo.",
  ui_story_32180401_1_102_dialog_content = "Con algo de entrenamiento, ella podría convertirse en una excelente contadora para Cloudrover.",
  ui_story_32180401_1_103_dialog_content = "Eso no tenía nada que ver con enviarla de vuelta a sus padres, ¿verdad?",
  ui_story_32180401_1_104_dialog_content = "Después de todo, mantenerla en el Gremio de Explorador Nublar es lo que haría un empresario astuto, ¿no es así?",
  ui_story_32180401_1_105_dialog_content = "Ahora no es el momento para eso.",
  ui_story_32180401_1_106_dialog_content = "O más bien, el mejor lugar para ella a su edad no es la guilda.",
  ui_story_32180401_1_107_dialog_content = "Lo sabía...",
  ui_story_32180401_1_108_dialog_content = "Tienes un lugar especial en tu corazón para Elena, ¿verdad? Ya sea cuidándola o hablando de ella...",
  ui_story_32180401_1_109_dialog_content = "No es agradable mirar dentro de la mente de una dama, mi estimado cliente.",
  ui_story_32180401_1_110_dialog_content = "Es simplemente un sentimiento. No se involucran poderes mentales.",
  ui_story_32180401_1_111_dialog_content = "¿Era tan obvio?",
  ui_story_32180401_1_112_dialog_content = "Supongo que tendré que aprender a controlar mejor mis emociones.",
  ui_story_32180401_1_113_dialog_content = "De hecho, hay otra razón importante por la que hice eso.",
  ui_story_32180401_1_114_dialog_content = "Solo... no quería que la chica creciera sin su familia.",
  ui_story_32180401_1_115_dialog_content = "Eso es todo.",
  ui_story_32180601_1_2_dialog_content = "Plaf—",
  ui_story_32180601_1_3_dialog_content = "¡Saludos, Curador!",
  ui_story_32180601_1_4_dialog_content = "Bien... bien, bastante animado...",
  ui_story_32180601_1_5_dialog_content = "La cantante y su banda están listos. ¿Comenzamos la actuación ahora?",
  ui_story_32180601_1_6_dialog_content = "¿Ahora mismo? No, deberíamos esperar a los invitados.",
  ui_story_32180601_1_7_dialog_content = "Señor, el alborotador ha sido atado y llevado al sótano.",
  ui_story_32180601_1_8_dialog_content = "¿Cómo quieres castigarlo para que aprenda su lección?",
  ui_story_32180601_1_9_dialog_content = "Castigar... ¿O deberíamos simplemente dejarlo solo para que se calme?",
  ui_story_32180601_1_10_dialog_content = "El líder de una pequeña pandilla quiere presentar sus respetos con un gesto de reverencia. ¿Te gustaría recibirlo?",
  ui_story_32180601_1_11_dialog_content = "¡Pasemos eso! Quién sabe qué pasará después de eso.",
  ui_story_32180601_1_12_dialog_content = "Entendido, me aseguraré de que renuncien a sus fantasías tontas.",
  ui_story_32180601_1_13_dialog_content = "¡Haremos todo lo posible para hacerle sentir orgulloso, señor!",
  ui_story_32180601_1_14_dialog_content = "¡Enorgullecerte!",
  ui_story_32180601_1_15_dialog_content = "Odio repetirme, pero no soy dueño de este lugar.",
  ui_story_32180601_1_16_dialog_content = "Su carácter humilde es admirable, señor. No cabe duda de ello.",
  ui_story_32180601_1_17_dialog_content = "Según el documento de la Sra. Sheol, tú eres el único y exclusivo curador aquí.",
  ui_story_32180601_1_18_dialog_content = "¡Por favor acepte nuestro más sincero respeto!!!",
  ui_story_32180601_1_19_dialog_content = "¿Cómo terminó así...?",
  ui_story_32180601_1_20_dialog_content = "Si lo hubiera sabido, no habría respondido a esa invitación...",
  ui_story_32180601_1_21_dialog_content = "<color=#e8d9bb>Estimado PlayerName, ha pasado un tiempo desde la última vez que hablamos, espero que esto te encuentre bien.</color>",
  ui_story_32180601_1_22_dialog_content = "<color=#e8d9bb>Con la expansión del Gremio de Explorador Nublar, tengo un asunto importante que discutir contigo.</color>",
  ui_story_32180601_1_23_dialog_content = "<color=#e8d9bb>Te agradecería si pudieras encontrar el tiempo para reunirte conmigo. Espero tener noticias tuyas.</color>",
  ui_story_32180601_1_24_dialog_content = "<color=#e8d9bb>Con amor, Sheol</color>",
  ui_story_32180601_1_25_dialog_content = "El elegante papel de carta y el sello de cera por sí solos gritan lujo.",
  ui_story_32180601_1_26_dialog_content = "Pero esta invitación, de la nada, me dio un mal presentimiento.",
  ui_story_32180601_1_27_dialog_content = "Y a Lady Sheol le gusta bromear con la gente. Aun así, dice que es un asunto importante.",
  ui_story_32180601_1_28_dialog_content = "La expedición conjunta aún está en marcha, y no podemos prescindir de la ayuda de la Señorita Sheol.",
  ui_story_32180601_1_29_dialog_content = "Supongo que tendré que irme.",
  ui_story_32180601_1_30_dialog_content = "¿Así que este es el nuevo club que la Señora Sheol acaba de adquirir?",
  ui_story_32180601_1_31_dialog_content = "¿No es esto un poco... demasiado lujoso? ¿Para qué está destinado?",
  ui_story_32180601_1_32_dialog_content = "¿Qué quieres decir?",
  ui_story_32180601_1_33_dialog_content = "Oh, lo siento, no estoy tratando de ser entrometido. La Señora Sheol me invitó.",
  ui_story_32180601_1_34_dialog_content = "Disculpe, usted es el Sr. Navegante, ¿verdad? ¡Por aquí, por favor!",
  ui_story_32180601_1_35_dialog_content = "La Señorita Sheol ha estado esperándote durante bastante tiempo, pero... ¿por qué estás vestido así?",
  ui_story_32180601_1_36_dialog_content = "¿Eh? Pensé que debería vestirme para tal ocasión.",
  ui_story_32180601_1_37_dialog_content = "Por supuesto. Por favor sígueme.",
  ui_story_32180601_1_38_dialog_content = "¡Está bien!",
  ui_story_32180601_1_39_dialog_content = "Este es el lugar.",
  ui_story_32180601_1_40_dialog_content = "A-¿Estás seguro?",
  ui_story_32180601_1_41_dialog_content = "Así es, la Señora Sheol me instruyó para escoltarte aquí a tu llegada.",
  ui_story_32180601_1_42_dialog_content = "Pensé que vendrías en tu bata de baño.",
  ui_story_32180601_1_43_dialog_content = "(Un baño lujoso... ¿Qué está pasando...)",
  ui_story_32180601_1_44_dialog_content = "Hmm, tal vez debería simplemente—",
  ui_story_32180601_1_45_dialog_content = "PlayerName, mi querido, finalmente estás aquí.",
  ui_story_32180601_1_46_dialog_content = "¿Podrías por favor no hacerme esperar aquí más tiempo?",
  ui_story_32180601_1_47_dialog_content = "M-May ¿Puedo entrar?",
  ui_story_32180601_1_48_dialog_content = "No veo nada malo en ello. Estamos aquí para discutir asuntos de negocios, ¿no es así?",
  ui_story_32180601_1_49_dialog_content = "Pasa.",
  ui_story_32180601_1_50_dialog_content = "¡Yo... yo entiendo ahora!",
  ui_story_32180601_1_51_dialog_content = "El vapor es tan espeso... Apenas puedo ver algo.",
  ui_story_32180601_1_52_dialog_content = "Qué decepción. ¿Por qué estás vestido tan formalmente? Esperaba invitarte a bañarte juntos.",
  ui_story_32180601_1_53_dialog_content = "¡¿Qué?!",
  ui_story_32180601_1_54_dialog_content = "Tan tímido que saliste corriendo, qué adorable, querido mío.",
  ui_story_32180601_1_55_dialog_content = "¿No lo mencioné en la invitación? He estado esperando con especial interés tu llegada.",
  ui_story_32180601_1_56_dialog_content = "Pero, pero ¿quién hubiera pensado que estaría en un baño público?",
  ui_story_32180601_1_57_dialog_content = "Esto es solo una parte del club, querido. ¿Por qué estás tan sorprendido? Estoy vestido adecuadamente. ¿Te gustaría comprobarlo?",
  ui_story_32180601_1_58_dialog_content = "El baño tiene 19 hierbas diferentes y el agua siempre está a la temperatura correcta.",
  ui_story_32180601_1_59_dialog_content = "Como mi invitado más estimado, su opinión es invaluable.",
  ui_story_32180601_1_60_dialog_content = "¡De acuerdo! Vamos a hacer que la jefa de limpieza te traiga una bata de baño. ¿Te gustaría acompañarme?",
  ui_story_32180601_1_61_option_content = "¿Por qué no... hablamos de negocios primero?",
  ui_story_32180601_1_62_dialog_content = "Jeje, realmente eres impaciente...",
  ui_story_32180601_1_63_dialog_content = "Pero disfruto de esta sed de oportunidades de negocio.",
  ui_story_32180601_1_64_option_content = "Por favor, deja de burlarte de mí...",
  ui_story_32180601_1_65_dialog_content = "Creo que esto todavía es parte de nuestro negocio.",
  ui_story_32180601_1_66_dialog_content = "Pero te ves tan sonrojado. Tal vez este no sea el mejor lugar para ti.",
  ui_story_32180601_1_67_dialog_content = "Puedes ir al salón primero. Estaré allí en un minuto para discutir nuestro asunto pendiente, el verdadero asunto.",
  ui_story_32180601_1_68_dialog_content = "¿Estás seguro de que es un asunto de negocios, verdad?",
  ui_story_32180601_1_69_dialog_content = "Por supuesto, y es algo que te beneficiará enormemente. También podrías esperarlo con ansias.",
  ui_story_32180601_1_70_dialog_content = "¿Hay algo en lo que pueda ayudar? Esta es tu tercera taza de té.",
  ui_story_32180601_1_71_dialog_content = "Estoy bien.",
  ui_story_32180601_1_72_dialog_content = "Y tus mejillas permanecen sonrojadas.",
  ui_story_32180601_1_73_dialog_content = "¿Podrías bajar el aire acondicionado para mí? Gracias.",
  ui_story_32180601_1_74_dialog_content = "<color=#e8d9bb>Criiiiik...</color>",
  ui_story_32180601_1_75_dialog_content = "Te pido disculpas por la espera, mi querida.",
  ui_story_32180601_1_76_dialog_content = "Aquí estás, ¿cuánto tiempo has pasado—",
  ui_story_32180601_1_77_dialog_content = "Solo quiero vestirme para combinar con tu traje.",
  ui_story_32180601_1_78_dialog_content = "Me tomó algún tiempo.",
  ui_story_32180601_1_79_dialog_content = "Guau, el vestido...",
  ui_story_32180601_1_80_dialog_content = "Estás impresionante todos los días, pero este vestido...",
  ui_story_32180601_1_81_dialog_content = "¿Bien? ¿Es lo suficientemente bueno para ti?",
  ui_story_32180601_1_82_dialog_content = "Deja de bromear... No es cuestión de ser lo suficientemente bueno o no. Me siento avergonzado ahora.",
  ui_story_32180601_1_83_dialog_content = "No digas eso, Sr. Navegante, después de todo, tú eres el dueño aquí.",
  ui_story_32180601_1_84_dialog_content = "¿Soy el... dueño?",
  ui_story_32180601_1_85_dialog_content = "Así es, te invité aquí hoy para transferir la propiedad de este club a tu cuidado.",
  ui_story_32180601_1_86_dialog_content = "Pfttt—Lo siento, tos, tos... ¿Qué fue eso?!",
  ui_story_32180601_1_87_dialog_content = "Como mi cliente más valioso, es justo que te invite a algo.",
  ui_story_32180601_1_88_dialog_content = "¡Eso no es solo algo!",
  ui_story_32180601_1_89_dialog_content = "Si no puedes explicarlo, absolutamente no lo aceptaré...",
  ui_story_32180601_1_90_dialog_content = "Por supuesto—tenía mis razones.",
  ui_story_32180601_1_91_dialog_content = "Este elegante club solía pertenecer a mi rival, un jefe del mercado negro.",
  ui_story_32180601_1_92_dialog_content = "Tomé el control de este club para infiltrarme en el mercado negro en la fiesta de gran inauguración.",
  ui_story_32180601_1_93_dialog_content = "Si la gente se entera de que me hice cargo de este club...",
  ui_story_32180601_1_94_dialog_content = "Parecerá que estoy intentando invadir su territorio. Es demasiado obvio, ¿no crees? Nadie va a aparecer.",
  ui_story_32180601_1_95_dialog_content = "Justo como esperaría de ti, muy perspicaz de hecho.",
  ui_story_32180601_1_96_dialog_content = "¿Qué más podría hacer? Podría convertirse en la fiesta de inauguración más tranquila en la historia de Umbraton...",
  ui_story_32180601_1_97_dialog_content = "... Solo mantén en secreto que lo compraste, ¿no está bien eso?",
  ui_story_32180601_1_98_dialog_content = "La red de inteligencia en Umbraton es más sofisticada de lo que te das cuenta. La noticia de la adquisición del club por un comprador anónimo ha sido difundida.",
  ui_story_32180601_1_99_dialog_content = "Con tanto en juego, no es sorpresa que la gente comience a especular sobre quién compró el lugar.",
  ui_story_32180601_1_100_dialog_content = "La preocupación más urgente en este punto es asegurar un comprador legítimo para mitigar la especulación externa innecesaria.",
  ui_story_32180601_1_101_dialog_content = "Entonces, ¿quién sería el comprador más adecuado para enviar invitaciones a los líderes de todos los gremios en Umbraton?",
  ui_story_32180601_1_102_dialog_content = "...¿Yo?",
  ui_story_32180601_1_103_dialog_content = "Realmente entiendes mis intenciones.",
  ui_story_32180601_1_104_dialog_content = "Así que esta es tu razón para darme el club...",
  ui_story_32180601_1_105_dialog_content = "Pero no es impecable, ¿no es así?",
  ui_story_32180601_1_106_dialog_content = "Por ejemplo, soy el Caelestite... ¿No es bastante conspicuo?",
  ui_story_32180601_1_107_dialog_content = "Y no suena bien... Quiero decir, mis antepasados llorarían si supieran que poseo un club así.",
  ui_story_32180601_1_108_dialog_content = "Entonces, ¿deberíamos aún...",
  ui_story_32180601_1_109_dialog_content = "Oh querido, no vas a decir que no, ¿verdad?",
  ui_story_32180601_1_110_dialog_content = "Uh, ¿tal vez deberíamos planificar las cosas?",
  ui_story_32180601_1_111_dialog_content = "No hay tiempo para eso. Las invitaciones han sido preparadas y están esperando su aprobación para su distribución.",
  ui_story_32180601_1_112_dialog_content = "Por supuesto, en tu nombre.",
  ui_story_32180601_1_113_dialog_content = "¿¡En mi nombre!?",
  ui_story_32180601_1_114_dialog_content = "No creo que nadie se creería mi historia, ni los gremios ni el jefe del mercado negro.",
  ui_story_32180601_1_115_dialog_content = "No, no, querida, realmente no sabes nada sobre tu encanto.",
  ui_story_32180601_1_116_dialog_content = "Eres el único individuo capaz de unificar las facciones dispares de Astra.",
  ui_story_32180601_1_117_dialog_content = "Solo tú puedes cerrar la brecha entre estos líderes desconfiados.",
  ui_story_32180601_1_118_dialog_content = "Por no mencionar, eres un socio importante para el Señor de las Sombras. Esto no es un secreto.",
  ui_story_32180601_1_119_dialog_content = "¿El gremio Umbraton? En efecto... es bastante coincidencia...",
  ui_story_32180601_1_120_dialog_content = "Con tu perspectiva positiva, optimismo e influencia incomparable en todo Astra...",
  ui_story_32180601_1_121_dialog_content = "Cuando quieres establecer un club en Umbraton para recopilar inteligencia, comerciar bienes y organizar reuniones para los líderes...",
  ui_story_32180601_1_122_dialog_content = "¿Quién se atrevería a decirte que no?",
  ui_story_32180601_1_123_dialog_content = "Casi me has convencido...",
  ui_story_32180601_1_124_dialog_content = "No te preocupes. Si alguien intenta meterte en problemas, te cubro la espalda.",
  ui_story_32180601_1_125_dialog_content = "Haré todo lo posible para apoyarte y protegerte, querido mío.",
  ui_story_32180601_1_126_dialog_content = "Confía en mí, y trabaja con mí, y ambos nos beneficiaremos.",
  ui_story_32180601_1_127_dialog_content = "Está bien...",
  ui_story_32180601_1_128_dialog_content = "Está bien, simplemente firmaré el acuerdo.",
  ui_story_32180601_1_129_dialog_content = "¡Gran decisión! Esta es una oportunidad de oro para ambos.",
  ui_story_32180601_1_130_dialog_content = "Correcto, tu plan me impresionó, eso es seguro.",
  ui_story_32180601_1_131_dialog_content = "Lo que es más importante... Creo en ti.",
  ui_story_32180601_1_132_dialog_content = "Invertir en ti seguramente vale algo, ¿verdad?",
  ui_story_32180601_1_133_dialog_content = "Humph, por supuesto.",
  ui_story_32180601_1_134_dialog_content = "Espero que entiendas, somos más que solo socios comerciales.",
  ui_story_32180601_1_135_dialog_content = "Estoy ansiosa por ver tu actuación en la fiesta de inauguración...",
  ui_story_32180601_1_136_dialog_content = "<color=#e8d9bb>Y aquí estoy, en la fiesta de apertura, esperando ansiosamente...</color>",
  ui_story_32180601_1_137_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_32180601_1_138_dialog_content = "¿Hmm? ¿Así que eres el nuevo dueño del club?",
  ui_story_32180601_1_139_dialog_content = "¿No es este solo un novato? ¿Realmente puede ser el curador aquí?",
  ui_story_32180601_1_140_dialog_content = "¿No me digas que planeas abrir un jardín de infancia aquí?",
  ui_story_32180601_1_141_dialog_content = "¡Jajajajaja!",
  ui_story_32180601_1_142_dialog_content = "(He hecho algunos enemigos en Umbraton, así que supongo que esto tenía que pasar...)",
  ui_story_32180601_1_143_dialog_content = "(No obstante, este es el primer día de negocio; ¡No puedo estropearlo!)",
  ui_story_32180601_1_144_dialog_content = "(Tengo que ayudar a la Señora Sheol...)",
  ui_story_32180601_1_145_dialog_content = "*tose* Ustedes dos, ¿saben con quién están hablando?",
  ui_story_32180601_1_146_dialog_content = "¿Eh? ¿Cómo te atreves a hablarme así en Umbraton? Di eso de nuevo y pondré este lugar patas arriba.",
  ui_story_32180601_1_147_dialog_content = "Si intentas algo, lo lamentarás. No saldrás de aquí con vida.",
  ui_story_32180601_1_148_dialog_content = "¿¡Qué dijiste!?",
  ui_story_32180601_1_149_dialog_content = "Lamento llegar tarde, Sr. Navegante.",
  ui_story_32180601_1_150_dialog_content = "¡¿...?!",
  ui_story_32180601_1_151_dialog_content = "¡Qué grosero de mi parte llegar tarde en una ocasión tan importante!",
  ui_story_32180601_1_152_dialog_content = "Por favor, asegúrate de aceptar el regalo del Gremio de Explorador Nublar.",
  ui_story_32180601_1_153_dialog_content = "¿Es eso... un cheque del Gremio de Explorador Nublar? ¿Y cuántos ceros tiene?!",
  ui_story_32180601_1_154_dialog_content = "¿Se supone que debo pagarle tanto por protección?",
  ui_story_32180601_1_155_dialog_content = "Mi oferta es una fracción minúscula de lo que costaría una expedición conjunta. Espero que la aceptes de todos modos.",
  ui_story_32180601_1_156_dialog_content = "Todo lo que pido es que reconozcas el patrocinio del Gremio de Explorador Nublar cuando discutas asuntos de importancia con el Gran Mariscal o Shadowlord.",
  ui_story_32180601_1_157_dialog_content = "Sería mi mayor honor.",
  ui_story_32180601_1_158_dialog_content = "Espera, ¿Señora Sheol, estás diciendo que él está conectado a la expedición conjunta...?",
  ui_story_32180601_1_159_dialog_content = "¿No es este tipo simplemente dependiente de sus conexiones con la sede y esos aficionados locos? ¿Los Lovegators?",
  ui_story_32180601_1_160_dialog_content = "Ustedes dos han estado haciendo bastante ruido desde antes...",
  ui_story_32180601_1_161_dialog_content = "Al nuevo curador no le gusta el ruido, creo que es hora de pedirte que te vayas...",
  ui_story_32180601_1_162_dialog_content = "No queremos molestar al curador y arruinar el trato para todos.",
  ui_story_32180601_1_163_dialog_content = "¡Por favor, regresa!",
  ui_story_32180601_1_164_dialog_content = "Escuché que el Señor Sombrío también quiere conocer al nuevo curador.",
  ui_story_32180601_1_165_dialog_content = "¡Oye, espera un minuto, cómo podríamos estar aquí para causar problemas!",
  ui_story_32180601_1_166_dialog_content = "Si el Señor Sombrío realmente nos honra con su presencia... ¡Por favor, permíteme hacer una inversión!",
  ui_story_32180601_1_167_dialog_content = "¡I-Igual aquí! Si hay una oportunidad de trabajar con Illumina, definitivamente estoy interesado.",
  ui_story_32180601_1_168_dialog_content = "¿Qué estás esperando? ¡Ve a agarrar un lugar!",
  ui_story_32180601_1_169_dialog_content = "¿Qué está pasando... Eh?!",
  ui_story_32180601_1_170_dialog_content = "<color=#e8d9bb>Así, la fiesta de apertura se convirtió en una ceremonia de firma.</color>",
  ui_story_32180601_1_171_dialog_content = "<color=#e8d9bb>Y los contratos firmados en solo medio día representan una cantidad de dinero sin precedentes...</color>",
  ui_story_32180601_1_172_dialog_content = "Uf... Me está matando...",
  ui_story_32180601_1_173_dialog_content = "¡Te has superado a ti mismo! Te estoy viendo bajo una luz completamente nueva.",
  ui_story_32180601_1_174_dialog_content = "No seas tan fácil en tu juicio. Creo que hubo varios tratos en marcha.",
  ui_story_32180601_1_175_dialog_content = "Te estaba dando señales, pero todo lo que hiciste fue fumar en tu pipa y presionarme para que firmara. Si algo sale mal, ¡no vengas a llorar a mí!",
  ui_story_32180601_1_176_dialog_content = "No te preocupes, todo lo que necesitas hacer es firmarlos. Tengo mucho más que considerar.",
  ui_story_32180601_1_177_dialog_content = "Descansa tranquilo, puedo manejar perfectamente la mayoría de los tratos; solo hay unos pocos.",
  ui_story_32180601_1_178_dialog_content = "Quizás está un poco fuera de control.",
  ui_story_32180601_1_179_dialog_content = "Entonces... ¿no vendría la pandilla a buscarme problemas?!",
  ui_story_32180601_1_180_dialog_content = "No, no, renuncio. ¡Elige a alguien más para el curador!",
  ui_story_32180601_1_181_dialog_content = "Oh no, eso no funcionará. Incluso tú debes adherirte al espíritu del contrato.",
  ui_story_32180601_1_182_dialog_content = "Además, ¿no lo has experimentado justo ahora?",
  ui_story_32180601_1_183_dialog_content = "¿La vida de los ricos? ¡Estoy bien como un Caelestite!",
  ui_story_32180601_1_184_dialog_content = "Eso no es lo que quise decir, estaba hablando sobre los servicios de seguridad del Gremio de Explorador Nublar.",
  ui_story_32180601_1_185_dialog_content = "Por favor, regresa.",
  ui_story_32180601_1_186_dialog_content = "Todo lo que necesitas hacer es hacer un trato más conmigo, ¡y los servicios de seguridad del Gremio Cloudrover serán gratuitos para ti para siempre!",
  ui_story_32180601_1_187_dialog_content = "¡Pero... me niego!",
  ui_story_32180601_1_188_dialog_content = "Eres tan tímido como siempre, ¿verdad, mi querido...",
  ui_story_32180601_1_189_dialog_content = "Sin embargo, dado que has firmado tantos contratos hoy, algunas personas podrían inevitablemente sentir celos. Sería mejor quedarse en el club y descansar bien.",
  ui_story_32180601_1_190_dialog_content = "Salir de Umbraton en medio de la noche no es seguro. Hay una alta probabilidad de que te secuestren.",
  ui_story_32180601_1_191_dialog_content = "¡¿Nunca mencionaste que había tal riesgo antes!?",
  ui_story_32180601_1_192_dialog_content = "Nunca te quedarías aquí si te lo dijera. Me temo que ya te habrías ido con tu envidiable Colossus.",
  ui_story_32180601_1_193_dialog_content = "Entonces, permíteme cuidarte bien esta noche y experimenta un gran baño!",
  ui_story_32180601_1_194_dialog_content = "¿Eh? ¿Ay? ¡¿Qué—!!!"
}
return config
